/* Initialize a new parser.
 */
func aqlParseInit(yypParser *yyParser) {
	yypParser.yyerrcnt = -1
	yypParser.yystack = append(yypParser.yystack[:0], yyStackEntry{})
}

/*
** This function makes a new parser.
*/
func aqlParseAlloc() *yyParser {
	yypParser := &yyParser{}
	aqlParseInit(yypParser)
	return yypParser
}

/* This template has no destructors.  The generator puts nothing at the
** next mark for a template of this kind. */

/*
** Pop the parser's stack once.
*/
func yy_pop_parser_stack(yypParser *yyParser) {
	n := len(yypParser.yystack) - 1
	if yyTrace != nil {
		yyTrace("Popping " + yyTokenName[yypParser.yystack[n].major])
	}
	yypParser.yystack[n] = yyStackEntry{}
	yypParser.yystack = yypParser.yystack[:n]
}

/*
** Clear all secondary memory allocations from the parser
*/
func aqlParseFinalize(yypParser *yyParser) {
	for len(yypParser.yystack) > 1 {
		yy_pop_parser_stack(yypParser)
	}
}

/*
** Find the appropriate action for a parser given the terminal
** look-ahead token iLookAhead.
*/
func yy_find_shift_action(iLookAhead YYCODETYPE, stateno YYACTIONTYPE) YYACTIONTYPE {
	if stateno > YY_MAX_SHIFT {
		return stateno
	}
	for {
		i := int(yy_shift_ofst[stateno])
		i += int(iLookAhead)
		if yy_lookahead[i] != iLookAhead {
			if YYFALLBACK != 0 {
				iFallback := yyFallback[iLookAhead]
				if iFallback != 0 {
					if yyTrace != nil {
						yyTrace("FALLBACK " + yyTokenName[iLookAhead] + " => " + yyTokenName[iFallback])
					}
					iLookAhead = iFallback
					continue
				}
			}
			if YYWILDCARD > 0 {
				j := i - int(iLookAhead) + YYWILDCARD
				if int(yy_lookahead[j]) == YYWILDCARD && iLookAhead > 0 {
					if yyTrace != nil {
						yyTrace("WILDCARD " + yyTokenName[iLookAhead] + " => " + yyTokenName[YYWILDCARD])
					}
					return yy_action[j]
				}
			}
			return yy_default[stateno]
		}
		return yy_action[i]
	}
}

/*
** Find the appropriate action for a parser given the non-terminal
** look-ahead token iLookAhead.
*/
func yy_find_reduce_action(stateno YYACTIONTYPE, iLookAhead YYCODETYPE) YYACTIONTYPE {
	i := int(yy_reduce_ofst[stateno])
	i += int(iLookAhead)
	return yy_action[i]
}

/*
** The following routine is called if the stack overflows.
*/
func yyStackOverflow(yypParser *yyParser) {
	yyarg := yypParser.yyarg
	_ = yyarg
	if yyTrace != nil {
		yyTrace("Stack Overflow!")
	}
	for len(yypParser.yystack) > 1 {
		yy_pop_parser_stack(yypParser)
	}
	/* Here code is inserted which will execute if the parser
	 ** stack every overflows */
	/******** Begin %stack_overflow code ******************************************/
	/******** End %stack_overflow code ********************************************/
	yypParser.yyarg = yyarg
}

/*
** Print tracing information for a SHIFT action
*/
func yyTraceShift(yypParser *yyParser, yyNewState int, zTag string) {
	if yyTrace != nil {
		zToken := yyTokenName[yypParser.yystack[len(yypParser.yystack)-1].major]
		if yyNewState < YYNSTATE {
			yyTrace(zTag + " '" + zToken + "', go to state " + yyitoa(yyNewState))
		} else {
			yyTrace(zTag + " '" + zToken + "', pending reduce " + yyitoa(yyNewState-YY_MIN_REDUCE))
		}
	}
}

/*
** Perform a shift action.
*/
func yy_shift(yypParser *yyParser, yyNewState YYACTIONTYPE, yyMajor YYCODETYPE, yyMinor aqlParseTOKENTYPE) {
	if YYSTACKDEPTH > 0 && len(yypParser.yystack) >= YYSTACKDEPTH {
		yyStackOverflow(yypParser)
		return
	}
	if yyNewState > YY_MAX_SHIFT {
		yyNewState += YY_MIN_REDUCE - YY_MIN_SHIFTREDUCE
	}
	var yytos yyStackEntry
	yytos.stateno = yyNewState
	yytos.major = yyMajor
	yytos.minor.yy0 = yyMinor
	yypParser.yystack = append(yypParser.yystack, yytos)
	yyTraceShift(yypParser, int(yyNewState), "Shift")
}

